MAP
    NAME "GeoStylerDemo"
    SIZE 800 800
    EXTENT 26.668678 58.339241 26.796582 58.409410
    PROJECTION
        "EPSG:4326"
    END
    OUTPUTFORMAT
        NAME "geojson"
        DRIVER "OGR/GEOJSON"
        MIMETYPE "application/json; subtype=geojson; charset=utf-8"
        FORMATOPTION "FORM=SIMPLE"
        FORMATOPTION "STORAGE=memory"
        FORMATOPTION "LCO:NATIVE_MEDIA_TYPE=application/vnd.geo+json"
        FORMATOPTION "USE_FEATUREID=true" # ensure GeoJSON output has an id property
    END

    # OpenLayers (ImageWMS with serverType 'mapserver') requests HiDPI images
    # with MAP_RESOLUTION = 90 x device pixel ratio. MapServer scales symbol
    # sizes by RESOLUTION / DEFRESOLUTION, so setting both to 90 keeps symbols
    # at the same visual size on any screen, and matching the SLD sizes used
    # for client-side styling.

    RESOLUTION 90
    DEFRESOLUTION 90

    # CONFIG "MS_ERRORFILE" "/etc/mapserver/tmp/mapserver.log"

    WEB
        IMAGEPATH "/etc/mapserver/tmp/" # end-slash is important!
        METADATA
            "ows_enable_request" "*"
            "ows_srs" "EPSG:4326 EPSG:3857"
            "ows_use_default_extent_for_getfeature" "false"
            "wfs_getfeature_formatlist" "geojson"
        END
    END

    # points
    INCLUDE "includes/notched-rect.sym"

    # lines
    INCLUDE "includes/arrow-wide.sym"

    # polygons
    INCLUDE "includes/square-spaced.sym"
    INCLUDE "includes/wave.sym"

    LAYER
        NAME "square-spaced"
        TYPE POLYGON
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/landuse_a.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        FILTER ("[fclass]" = "scrub")
        INCLUDE "includes/square-spaced.class"
    END

    LAYER
        NAME "wave"
        TYPE POLYGON
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/water_a.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        FILTER ("[fclass]" = "riverbank")
        INCLUDE "includes/wave.class"
    END

    LAYER
        NAME "notched-rect"
        TYPE POINT
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/pois.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        FILTER ("[fclass]" = "restaurant")
        INCLUDE "includes/notched-rect.class"
    END

    LAYER
        NAME "arrow-wide"
        TYPE LINE
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/roads.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        FILTER ("[fclass]" = "tertiary")
        INCLUDE "includes/arrow-wide.class"
    END

END